import{_ as i}from"./chunks/mac-security-settings.DOF-7oNi.js";import{_ as t,o as e,c as l,a0 as s}from"./chunks/framework.CShDTZbC.js";const k=JSON.parse('{"title":"Распространенная проблема при установке в macOS - Решение для \\"приложение повреждено\\"","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guide/mac-installation-issue.md","filePath":"ru/guide/mac-installation-issue.md"}'),o={name:"ru/guide/mac-installation-issue.md"};function p(r,a,n,h,u,d){return e(),l("div",null,[...a[0]||(a[0]=[s('<h1 id="распространенная-проблема-при-установке-в-macos-решение-для-приложение-повреждено" tabindex="-1">Распространенная проблема при установке в macOS - Решение для &quot;приложение повреждено&quot; <a class="header-anchor" href="#распространенная-проблема-при-установке-в-macos-решение-для-приложение-повреждено" aria-label="Permalink to &quot;Распространенная проблема при установке в macOS - Решение для &quot;приложение повреждено&quot;&quot;">​</a></h1><p>При установке OTools или других сторонних приложений в macOS вы можете столкнуться с сообщением примерно следующего содержания: &quot;xxx.app поврежден, невозможно открыть, вы должны переместить его в корзину&quot;. Как правило, это связано с настройками безопасности macOS.</p><h2 id="почему-возникает-эта-проблема" tabindex="-1">Почему возникает эта проблема? <a class="header-anchor" href="#почему-возникает-эта-проблема" aria-label="Permalink to &quot;Почему возникает эта проблема?&quot;">​</a></h2><p>macOS имеет гораздо более строгий контроль над программами по сравнению с Windows. При установке приложений, не являющихся частью App Store, часто появляются сообщения типа &quot;xxx.app поврежден&quot;. Начиная с macOS 10.15, Apple дополнительно ограничила права доступа для неподписанных приложений, что делает такие проблемы более частыми.</p><h2 id="решения" tabindex="-1">Решения <a class="header-anchor" href="#решения" aria-label="Permalink to &quot;Решения&quot;">​</a></h2><h3 id="метод-1-настроика-разрешения-загрузки-приложении-из-любых-источников" tabindex="-1">Метод 1: Настройка разрешения загрузки приложений из &quot;Любых источников&quot; <a class="header-anchor" href="#метод-1-настроика-разрешения-загрузки-приложении-из-любых-источников" aria-label="Permalink to &quot;Метод 1: Настройка разрешения загрузки приложений из &quot;Любых источников&quot;&quot;">​</a></h3><ol><li>Откройте &quot;Системные настройки -&gt; Защита и конфиденциальность -&gt; Общие&quot;</li><li>Проверьте, активирована ли опция &quot;Разрешить приложения, загруженные из:&quot; и уже ли включена опция &quot;Любые источники&quot;</li><li>Если не включена, щелкните значок маленького замка в левом нижнем углу, чтобы разблокировать, затем выберите &quot;Любые источники&quot;</li></ol><p><img src="'+i+'" alt=""></p><p>Если вы не видите опцию &quot;Любые источники&quot; в настройках, откройте Терминал и введите следующую команду:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --master-disable</span></span></code></pre></div><p>Введите пароль для входа в систему вашего компьютера, как указано, затем нажмите Ввод. После этого вы увидите, что в настройках появилась опция &quot;Любые источники&quot;.</p><p>Обычно после этой настройки приложение можно установить нормально. Однако если ваша версия macOS новее, вам все равно может потребоваться попробовать следующий метод.</p><h3 id="метод-2-обход-проверки-gatekeeper-от-apple" tabindex="-1">Метод 2: Обход проверки Gatekeeper от Apple <a class="header-anchor" href="#метод-2-обход-проверки-gatekeeper-от-apple" aria-label="Permalink to &quot;Метод 2: Обход проверки Gatekeeper от Apple&quot;">​</a></h3><p>Если первым методом проблема не решается, вы можете попробовать следующие шаги:</p><ol><li>Откройте Терминал</li><li>Введите следующую команду, но пока не нажимайте Ввод:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span></span></code></pre></div><ol start="3"><li>В Finder найдите OTools.app в папке &quot;Программы&quot;</li><li>Перетащите OTools.app в окно терминала, после чего автоматически добавится путь к приложению к команде</li><li>Нажмите Ввод, введите свой пароль, после завершения вы сможете запустить приложение напрямую</li></ol><h3 id="метод-3-открытие-через-правыи-клик-подходит-для-первои-установки" tabindex="-1">Метод 3: Открытие через правый клик (подходит для первой установки) <a class="header-anchor" href="#метод-3-открытие-через-правыи-клик-подходит-для-первои-установки" aria-label="Permalink to &quot;Метод 3: Открытие через правый клик (подходит для первой установки)&quot;">​</a></h3><p>Для первой установки также можно использовать:</p><ol><li>Найдите OTools.app в Finder</li><li>Щелкните правой кнопкой мыши (или удерживайте клавишу Control и кликните)</li><li>Выберите &quot;Открыть&quot;</li><li>В появившемся окне предупреждения безопасности нажмите &quot;Открыть&quot;</li></ol><h2 id="важные-примечания" tabindex="-1">Важные примечания <a class="header-anchor" href="#важные-примечания" aria-label="Permalink to &quot;Важные примечания&quot;">​</a></h2><ul><li>OTools — это легальное настольное приложение, созданное с использованием фреймворка Tauri</li><li>Ваш компьютер не подвергается воздействию вредоносного программного обеспечения</li><li>Эта проблема вызвана политикой безопасности Apple, а не самим приложением</li></ul>',22)])])}const m=t(o,[["render",p]]);export{k as __pageData,m as default};
